import sys
sys.setrecursionlimit(1000000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    MOD = 1000000007

    present_nodes = []
    missing_nodes = []
    for i in range(n):
        node_idx = i + 1
        val = a[i]
        if val == 0:
            missing_nodes.append(node_idx)
        else:
            present_nodes.append((val, node_idx))

    if len(present_nodes) == n:
        perm = [0] * (n + 1)
        for val, pos in present_nodes:
            perm[pos] = val

        dist = [-1] * (n + 1)
        stack = [(1, 0)]
        dist[1] = 0
        while stack:
            u, d = stack.pop()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = d + 1
                    stack.append((v, dist[v]))

        valid = True
        for i in range(1, n + 1):
            if (dist[i] % 2) != (dist[perm[i]] % 2):
                valid = False
                break

        if valid:
            print(1)
        else:
            print(0)
        return

    if len(missing_nodes) == 0:
        print(0)
        return

    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    visited = [False] * (n + 1)

    stack = [1]
    visited[1] = True
    depth[1] = 0
    parent[1] = 0

    order = []
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                stack.append(v)

    missing_set = set(missing_nodes)
    present_map = {}
    for val, pos in present_nodes:
        present_map[val] = pos

    fixed_parity = {}
    for val, pos in present_nodes:
        orig_pos = val
        if depth[orig_pos] % 2 != depth[pos] % 2:
            print(0)
            return
        fixed_parity[val] = depth[pos] % 2

    total_missing = len(missing_nodes)
    missing_even = 0
    missing_odd = 0
    for node in missing_nodes:
        if depth[node] % 2 == 0:
            missing_even += 1
        else:
            missing_odd += 1

    needed_even = 0
    needed_odd = 0
    for val in range(1, n + 1):
        if val not in present_map:
            target_parity = fixed_parity.get(val, None)
            if target_parity is None:
                pass
            else:
                if target_parity == 0:
                    needed_even += 1
                else:
                    needed_odd += 1

    if needed_even > missing_even or needed_odd > missing_odd:
        print(0)
        return

    ways = 1
    for _ in range(needed_even):
        ways = (ways * missing_even) % MOD
        missing_even -= 1

    for _ in range(needed_odd):
        ways = (ways * missing_odd) % MOD
        missing_odd -= 1

    remaining = missing_even + missing_odd
    if remaining > 0:
        fact = 1
        for i in range(1, remaining + 1):
            fact = (fact * i) % MOD
        ways = (ways * fact) % MOD

    print(ways)

if __name__ == "__main__":
    main()
